steps:
set -eu
while IFS= read -r p; do
  dir=${p%/*}
  base=${p##*/}
  rest=${base#.}
  if [[ $rest == *.* ]]; then
    ext=${base##*.}
    stem=${base%.*}
  else
    ext=
    stem=$base
  fi
  printf '%s|%s|%s|%s\n' "$dir" "$base" "$stem" "$ext"
done < /home/eval/data/paths.txt > /home/eval/data/parts.txt
